          "service_type"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "send_reminder",
      "description": "Send appointment reminder",
      "parameters": {
        "type": "object",
        "properties": {
          "appointment_id": {
            "type": "string"
          },
